package org.example.behavioral_pattern.observer_pattern.spring_boot;public class Order {    private  String id;    private  String customerEmail;    private  double amount;    public Order(String id, String customerEmail, double amount) {        this.id = id;        this.customerEmail = customerEmail;        this.amount = amount;    }    public String getId() {        return id;    }    public void setId(String id) {        this.id = id;    }    public String getCustomerEmail() {        return customerEmail;    }    public void setCustomerEmail(String customerEmail) {        this.customerEmail = customerEmail;    }    public double getAmount() {        return amount;    }    public void setAmount(double amount) {        this.amount = amount;    }}